package org.tomdang.critter.journal;
import javax.sql.DataSource;import java.sql.*;import java.util.*;
public final class PostgresCritterJournalRepository implements CritterJournalRepository{
	private final DataSource dataSource;public PostgresCritterJournalRepository(DataSource dataSource){this.dataSource=Objects.requireNonNull(dataSource);}
	public Optional<CritterJournalEntry> find(UUID playerId,String critterId){String sql="SELECT knowledge,observations,successful_hunts,first_seen_at,last_seen_at FROM tomblock.critter_journal WHERE player_id=? AND critter_id=?";try(var connection=dataSource.getConnection();var statement=connection.prepareStatement(sql)){statement.setObject(1,playerId);statement.setString(2,critterId.toUpperCase(Locale.ROOT));try(var result=statement.executeQuery()){if(!result.next())return Optional.empty();return Optional.of(new CritterJournalEntry(playerId,critterId.toUpperCase(Locale.ROOT),CritterKnowledge.valueOf(result.getString(1)),result.getInt(2),result.getInt(3),result.getTimestamp(4).toInstant(),result.getTimestamp(5).toInstant()));}}catch(SQLException exception){throw new IllegalStateException("Could not load critter journal",exception);}}
	public void save(CritterJournalEntry entry){String sql="INSERT INTO tomblock.critter_journal(player_id,critter_id,knowledge,observations,successful_hunts,first_seen_at,last_seen_at) VALUES(?,?,?,?,?,?,?) ON CONFLICT(player_id,critter_id) DO UPDATE SET knowledge=EXCLUDED.knowledge,observations=EXCLUDED.observations,successful_hunts=EXCLUDED.successful_hunts,last_seen_at=EXCLUDED.last_seen_at";try(var connection=dataSource.getConnection();var statement=connection.prepareStatement(sql)){statement.setObject(1,entry.playerId());statement.setString(2,entry.critterId().toUpperCase(Locale.ROOT));statement.setString(3,entry.knowledge().name());statement.setInt(4,entry.observations());statement.setInt(5,entry.successfulHunts());statement.setTimestamp(6,Timestamp.from(entry.firstSeenAt()));statement.setTimestamp(7,Timestamp.from(entry.lastSeenAt()));statement.executeUpdate();}catch(SQLException exception){throw new IllegalStateException("Could not save critter journal",exception);}}
}
